using System;using System.Linq;using System.Collections.Generic;using System.Threading;using System.Threading.Tasks;using System.Web.Script.Serialization;using ReplierDesktop;
public static class AudienceChecks {
 static void Check(bool b,string s){if(!b)throw new Exception(s);Console.WriteLine("PASS "+s);}
 public static int Main(){try{var json=new JavaScriptSerializer();var raw=json.DeserializeObject("{\"mutations\":[{\"payload\":{\"commentEntityPayload\":{\"properties\":{\"content\":{\"content\":\"시간 제한인데 동시에 조작하네요ㅋㅋ\"}}}}}],\"other\":{\"commentRenderer\":{\"contentText\":{\"runs\":[{\"text\":\"컨트롤 보면서 계속 감탄했어요\"}]}}}}");
 var parsed=AudienceComments.Parse(raw);Check(parsed.Length==2,"public legacy and entity comment text parsed without author profiles");
 Check(AudienceComments.Clean(new[]{"제 메일은 sample@example.com 신청주세요","구독 부탁드립니다 여러분","이 조작이 정말 신기하네요","이 조작이 정말 신기하네요"}).SequenceEqual(new[]{"이 조작이 정말 신기하네요"}),"advertising contact information and exact duplicates are excluded");
 string reference="시간 제한인데 동시에 조작하는 게 진짜 대단하네요ㅋㅋ";Check(AudienceComments.Copies(reference,new[]{reference}),"copied original sentence is excluded");Check(AudienceComments.Copies("시간 제한인데 동시에 조작하는 게 진짜 대단하네요ㅎㅎ",new[]{reference}),"minor punctuation/laughter edit does not disguise copying");Check(!AudienceComments.Copies("시간 안에 이걸 다 챙기는 게 신기하네요",new[]{reference}),"new reaction on the same subject is allowed");
 using(var model=new LocalModel("unused")){var v=new Video{Title="제한시간 컨트롤"};var e=new Dictionary<string,CaptionCue>{{"c0",new CaptionCue{Text="제한시간이 있어서 빨리 동시에 조작해야 합니다."}}};var sample=new AudienceSample{Comments=new[]{reference,"손으로 이걸 동시에 챙기는 게 신기하네요"},Status="공개 댓글 참고"};
 var angles=AudienceComments.Plan(model,v,e,sample,CancellationToken.None,(body,t)=>Task.FromResult("{\"angles\":[{\"cue\":\"c0\",\"topic\":\"시간 안에 동시에 조작하는 일\",\"tone\":\"짧은 놀람\",\"sources\":[0,1]}]}")).GetAwaiter().GetResult();Check(angles.Length==1&&angles[0].Sources[0]==0,"reaction note links to an actual caption and actual public comment index");
 var bad=AudienceComments.Plan(model,v,e,sample,CancellationToken.None,(body,t)=>Task.FromResult("{\"angles\":[{\"cue\":\"fake\",\"topic\":\"없는 내용\",\"tone\":\"짧은 놀람\",\"sources\":[0,1]}]}")).GetAwaiter().GetResult();Check(bad.Length==0,"invented caption linkage cannot enter writing guidance");
 var none=AudienceComments.Plan(model,v,e,new AudienceSample(),CancellationToken.None,(body,t)=>{throw new Exception("Should not call model");}).GetAwaiter().GetResult();Check(none.Length==0,"no real comments uses caption fallback without fabricated references");
 var scene=new SceneReading{Topic="동시 조작",Situation="시간 제한",Outcome="상황 확인",Nuance="담담함",Angles=new string[0],EvidenceIds=new[]{"c0"}};
 var material=new Dictionary<string,string>{{"c0",json.Serialize(new{context_version=2,scene=scene,title=v.Title,caption=e["c0"].Text,raw_sources=new[]{new{cue_id="c0",text=e["c0"].Text}},avoid_names=new string[0],game_names=new string[0],audience_comments=sample.Comments,audience_angles=angles,audience_status=sample.Status})}};
 int writes=0;string[] drafts={"여러 군데를 동시에 챙기는 게 신기하네요","판단할 게 많아서 계속 보게 되네요","시간 안에 다 끝내는 게 놀랍네요","어디부터 봐야 할지 고민되네요ㅋㅋ","조작 순서가 정말 중요하겠네요"};
 var writer=new SceneWriter(model,(body,t)=>{var req=SceneMaterial.Json(json.Serialize(body));var msgs=(object[])CaptionService.Get(req,"messages");var input=SceneMaterial.Json((string)CaptionService.Get(msgs.Last(),"content"));Check(CaptionService.Get(input,"reference_style") is string&&CaptionService.Get(input,"reference_reactions")==null&&CaptionService.Get(input,"actual_context") is string,"writer receives audience style and original video facts without importing viewer claims as facts");return Task.FromResult(json.Serialize(new{comments=new[]{drafts[(writes++)%drafts.Length]}}));});
 var written=writer.Generate(e,material,new string[0],CancellationToken.None,(text,id,seen)=>new CommentSuggestion{Text=text,CueId=id},1).GetAwaiter().GetResult();Check(written.Comments.Count>0&&written.ReferenceComments.Length==2,"copied debug retains the actual reference pool used for writing");
 var diverse=new Dictionary<string,CaptionCue>();for(int i=0;i<5;i++)diverse.Add("c"+i,new CaptionCue{Text="서로 다른 구간의 관측 가능한 내용 "+i});
 Check(AudienceComments.Attach(material,diverse,sample,angles).Count==1,"writing keeps the original scene selected context instead of reopening unclear unrelated ASR windows");
 var multi=SceneMaterial.Json(material["c0"]) as Dictionary<string,object>;((Dictionary<string,object>)multi["scene"])["EvidenceIds"]=diverse.Keys.ToArray();var approved=new Dictionary<string,string>{{"c0",json.Serialize(multi)}};var attached=AudienceComments.Attach(approved,diverse,sample,angles);writes=0;
 var diverseWriter=new SceneWriter(model,(body,t)=>Task.FromResult(json.Serialize(new{comments=new[]{drafts[(writes++)%drafts.Length]}})));
 var varied=diverseWriter.Generate(diverse,attached,new string[0],CancellationToken.None,(text,id,seen)=>new CommentSuggestion{Text=text,CueId=id},5).GetAwaiter().GetResult();
 Check(varied.Comments.Select(c=>c.CueId).Distinct().Count()==5,"one reference angle cannot force all drafts onto the same caption window");
 }return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
